extensionAttribute.scriptContentsMac:
#!/bin/zsh
# Updated by SecurityShrimp 2026 # Recovery Volume Present Extension Attribute # Targets macOS 12 through 26 (Tahoe) # The legacy HFS+ "Recovery HD" partition (10.7-10.12) was replaced by an # APFS "Recovery" volume in the boot container in macOS 10.13+. This checks # for both so it remains correct on any modern Mac.
if /usr/sbin/diskutil apfs list 2>/dev/null | /usr/bin/grep -Eq 'Name:[[:space:]]+Recovery'; then echo "<result>Present</result>" elif /usr/sbin/diskutil list 2>/dev/null | /usr/bin/grep -q 'Recovery HD'; then echo "<result>Present</result>" else echo "<result>Not Present</result>" fi
